export function ResourcePage({title,description,columns,rows,action}:{title:string;description:string;columns:string[];rows:string[][];action:string}){return <><header className="mb-8 flex items-end justify-between"><div><h1 className="text-3xl font-black">{title}</h1><p className="muted mt-2">{description}</p></div><button className="rounded-xl bg-[#00c8ff] px-4 py-3 text-sm font-black text-[#050b1e]">{action}</button></header><div className="panel overflow-x-auto"><table className="w-full min-w-[700px] text-left"><thead className="border-b border-[#20365e] text-xs uppercase tracking-wider text-[#8da2c8]"><tr>{columns.map(c=><th className="px-5 py-4" key={c}>{c}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr className="border-b border-[#20365e]/60 last:border-0" key={i}>{row.map((cell,j)=><td className="px-5 py-4 text-sm" key={j}>{cell}</td>)}</tr>)}</tbody></table></div></>}
